learn=[('Enable tracked file backups', 'Use enableFileCheckpointing and replay-user-messages. The SDK tracks edits through Write, Edit and NotebookEdit; the lab performs real Edit and Write calls.'), ('Capture checkpoint identities', 'Save the replayed user-message UUID together with its session ID. These identify a pre-turn file state, not an arbitrary result message or a Git commit.'), ('Preview and rewind', 'Use rewindFiles(id, { dryRun: true }) to inspect the native preview, then rewindFiles(id) to restore. Modified files recover their old content; tracked newly created files are removed.'), ('Keep safe restore points', 'Automatically rewind when a real Node test fails. Or capture multiple turns, inspect their pre-turn snapshots and choose a known checkpoint through the web menu.'), ('Rewind from a later process', 'Save and reload the session/checkpoint pair, open an empty resumed query with checkpointing enabled, then restore. Local transcripts and backup files must still be available.'), ('Understand what remains', 'Conversation history stays intact. A distinct file changed only by Bash remains untracked. Checkpoints are session-specific, not a complete filesystem or remote storage snapshot.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3142\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, API access and available credit. Windows requires Git Bash for the fixed shell comparison and may require it for SDK startup. No remote storage account or GitHub token is required.', 'node --version\nnpm --version'), ('Install and create .env', 'Install locked dependencies, preserve an existing .env and enter your API key privately. The npm script loads the same environment used by the SDK worker.', 'cd .\\agent-sdk\\lesson42-checkpointing\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open. Use the five navigation buttons to explore learning goals, setup, UML, source and the actual lab.', 'npm start\n# http://127.0.0.1:3142'), ('Compare restore, preview and created files', 'Restore edits the existing TypeScript fixture and restores its original bytes. Preview performs only dryRun. Created writes a new note.txt and removes it through real rewind. Inspect all three file snapshots and native results.', 'npm run sample:env -- restore\nnpm run sample:env -- preview\nnpm run sample:env -- created'), ('Practise recovery and a restore menu', 'Validation runs a real Node test before an intentional agent-written bug, observes the failure, rewinds automatically and runs the test again. Menu captures two turns; choose a checkpoint, inspect its pre-turn snapshot, then click Rewind selected checkpoint. The CLI automatically chooses the second checkpoint.', 'npm run sample:env -- validation\nnpm run sample:env -- menu\nnpm run sample:env -- restart'), ('Verify the boundaries', 'Restart reloads IDs and starts a later process while retaining local backups. History proves that recalling an earlier edit still works after restoring files. Untracked uses one exact Bash command on a distinct file never edited by Write/Edit. Invalid attempts a checkpoint from another session. All classroom data is cleaned up after each run.', 'npm run sample:env -- history\nnpm run sample:env -- untracked\nnpm run sample:env -- invalid\nnpm test')]
specs=[('Validate the experiment', 'src/modes.ts', 'export function validateConfig', 'Accept only fixed classroom modes. Requests cannot provide arbitrary files, shell commands, resume IDs or checkpoint UUIDs.', 0, 1, 7), ('Prepare a disposable TypeScript project', 'src/workspace.ts', 'await writeFile(join(cwd, "math.mts"), BASE);', 'Seed a small TypeScript fixture and a real Node test inside an isolated project, home and SDK config. The original content is independently observed.', 1, 4, 6), ('Enable backups and user replay', 'src/worker.ts', 'enableFileCheckpointing: true,', 'Enable SDK checkpointing and replay-user-messages. acceptEdits is constrained by a guard to fixed classroom paths and bounded inputs.', 1, 2, 9), ('Guard tracked edit tools', 'src/policy.ts', 'if (name === "Read")', 'Only the fixed fixtures can be read or edited. The shell demonstration needs its explicit exact-command capability; arbitrary tools and paths are rejected.', 2, 4, 9), ('Capture the user checkpoint UUID', 'src/worker.ts', 'message.type === "user" && message.uuid', 'Capture the actual replayed user-message UUID once per query, paired with its actual SDK session ID.', 2, 1, 4), ('Associate each checkpoint with its pre-turn state', 'src/agent.ts', 'if (type === "checkpoint")', 'The host labels native checkpoint IDs and stores independently read pre-turn snapshots for teaching. SDK backups, rather than host snapshots, perform restoration.', 1, 3, 5), ('Open a resumed rewind connection', 'src/worker.ts', 'const active = query', 'Use an empty prompt with resume and checkpointing enabled. The control operation runs in a new actual SDK worker.', 1, 2, 6), ('Preview restoration without writes', 'src/worker.ts', 'const preview = await active.rewindFiles', 'Capture the native dry-run result. Preview must not change current file bytes or remove newly created files.', 2, 3, 4), ('Apply real rewind', 'src/worker.ts', 'if (!request.dryRun && preview.canRewind)', 'Only apply when requested and the native preview allows it. Capture native canRewind and skippedLinks data; inspect actual files afterward.', 3, 4, 5), ('Recover when validation fails', 'src/agent.ts', 'const failed = await w.test();', 'Run the real Node test against the agent-written bug. A failure triggers SDK rewind, followed by another real test run.', 1, 2, 5), ('Choose one known restore point', 'src/agent.ts', 'const choice = chooseSession', 'Bind the browser choice to known checkpoint IDs for this run. The selected pre-turn state determines which later edits are undone.', 0, 1, 8), ('Reload restore identifiers later', 'src/agent.ts', 'const saved = await w.saveIds', 'Persist and reload the session/checkpoint pair, then rewind in a later worker. Local SDK history and backups remain available.', 1, 3, 3), ('Verify conversation history remains', 'src/agent.ts', 'if (c.mode === "history")', 'After files are restored, resume the same conversation and recall the previously written marker without reading the file. File restoration does not erase that history.', 1, 2, 6)]
document('/','File checkpoints <em>and rewind.</em>','Capture real checkpoints, preview file changes and restore safely.','<div class="flow"><div><b>01 · Capture</b><p>User UUID + session ID</p></div><span>→</span><div><b>02 · Preview</b><p>Inspect a dry run</p></div><span>→</span><div><b>03 · Rewind</b><p>Restore tracked files</p></div></div><section class="panel" id="controls"><h2>Explore checkpointing and rewind</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Checkpoint experiment</label><select id="mode"><option value="restore">Tracked edit · restore original files</option><option value="preview">Dry run · preview without restoring</option><option value="created">Created file · remove on rewind</option><option value="validation">Failing test · automatic recovery</option><option value="menu">Restore menu · choose a checkpoint</option><option value="restart">Later process · reload restore identifiers</option><option value="history">Boundary · files rewind, conversation stays</option><option value="untracked">Boundary · untracked shell file stays</option><option value="invalid">Wrong session · reject unrelated checkpoint</option></select><button id="run" class="primary" disabled>Run checkpoint experiment →</button><p class="meta">Real SDK edits and rewind controls act only on disposable classroom files. Restore Menu waits for your click. The shell comparison permits one fixed command on an untracked fixture. SDK threshold: $0.35 per query. All temporary files and backups are removed after evidence capture.</p></section><section class="step" id="picker-panel"><h2>Choose a captured restore point</h2><p id="choice-status" class="note">Restore Menu pauses for your choice. Inspect the pre-turn snapshot, then click Rewind selected checkpoint.</p><label for="session-picker">Captured user-message checkpoint UUIDs</label><select id="session-picker"><option>No stored sessions yet</option></select><button id="resume-session" class="primary" disabled>Rewind selected checkpoint →</button></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Host configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Each query and its exact checkpointing and resume options appear in the observation selector.</p></section></div><section class="step" id="comparison-panel"><h2>Actual query responses</h2><div class="grid" id="branch-cards"></div></section><section class="step" id="results-panel"><h2>Actual results, session IDs and processes</h2><div class="table"><table><thead><tr><th>Query</th><th>Stage</th><th>Node PID</th><th>Status</th><th>session_id</th><th>Result text</th></tr></thead><tbody id="result-history"></tbody></table></div><pre class="json-view"><code id="latest-result" class="language-json">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Captured checkpoint catalog</h2><pre class="json-view"><code id="catalog" class="language-json">[]</code></pre></section><section class="step" id="messages-panel"><h2>Selected checkpoint: pre-turn snapshot</h2><pre class="json-view"><code id="messages" class="language-json">{}</code></pre><p>This is the host snapshot observed before the query that yielded this actual checkpoint UUID. The SDK performs restoration from its own backups.</p></section><section class="step" id="files-panel"><h2>Follow the real file changes</h2><div class="grid"><article><h3>Before the edit</h3><pre><code id="file-before" class="language-typescript"></code></pre></article><article><h3>After the tracked edit</h3><pre><code id="file-edited" class="language-typescript"></code></pre></article><article><h3>After preview / rewind</h3><pre><code id="file-after" class="language-typescript"></code></pre></article></div></section><section class="step" id="storage-panel"><h2>Actual snapshots, rewind results and validation</h2><pre class="json-view"><code id="storage" class="language-json">{}</code></pre><p>Compare exact file content, native dry-run/apply results, test outcomes and local backup paths. Rewinding does not rewind conversation history.</p></section><section class="step" id="observation-panel"><h2>Inspect actual query and worker events</h2><label for="observation-select">Observed arrival sequence</label><select id="observation-select"><option>No observations yet</option></select><pre class="json-view"><code id="selected-observation" class="language-json">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent run evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><button id="download">Download actual observations</button></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Understand tracked backups, safe restore points and conversation boundaries.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your .env configuration</h2>'+snippet(env,'dotenv')+'<p>Only your model key is required. Keep it local and restart after edits. Existing shell variables take precedence.</p></section><section class="note"><h3>Troubleshooting</h3><p>Use Node 24+, API credit and a supported model. Configure Git Bash on Windows if requested. If the port is occupied, use the printed existing-app URL or change PORT. Restore Menu waits for your checkpoint selection and click. Other scenarios finish automatically. Checkpoint selection expires after two minutes. Change PORT if 3142 is occupied.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install the SDK, configure your key and run the classroom comparisons.',body)
steps=[];arrows=[];lanes=['Student UI','TypeScript host','SDK worker process','Local backups','Project files']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 42 · Capture → preview → rewind → verify</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{min(x1,x2)+10}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The diagram groups actual SDK edits, checkpoint capture, local backups and rewind controls. Numbered steps group teaching scenarios rather than one universal sequence.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked session workflow steps"></div>'+walk)

reference=[('What this app actually runs', 'Real SDK Read/Edit/Write calls change disposable classroom fixtures. Real rewindFiles controls restore them. Validation uses a real Node child process. The restore menu requires an actual browser choice. NotebookEdit is part of the SDK contract but is not invoked in this lab.'), ('Preview and link safety', 'A dry run shows planned changes without modifying files. A real rewind can skip unsafe links or unavailable backups. The app records native results and independently compares file bytes; it does not claim preview alone proves successful restoration.'), ('Conversation versus files', 'Rewind restores files without erasing prior prompts, tool results or conversational context. The History test recalls EDITED-42 after the actual file returns to BASE-42.'), ('Shell and subagent limits', 'A file changed only through Bash is not tracked. If a main-conversation Write/Edit had already tracked that file, a rewind can restore it. The lab uses a separate untracked file to show this boundary. Subagent edits have analogous limits; this lab does not invoke subagents.'), ('Local, session-specific restore points', 'Use checkpoint UUIDs only with their original session and retain the local backups. IDs alone cannot restore files after backups are lost. Directory operations and remote filesystem state are not a complete checkpoint snapshot.'), ('Conflict with external session stores', 'The SDK rejects checkpointing combined with sessionStore because file backup blobs are not mirrored by that interface. This lab uses isolated local SDK storage rather than the Lesson 41 adapter.'), ('Validation and lifetime', 'The tests check guarded paths and commands, restore-choice capabilities, actual fixture failure/recovery, snapshot hashes and startup handling. All temporary classroom projects, transcripts and backups are removed after evidence collection. Keep Git as an independent project safety net.')]
document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has source-linked coloured code.',cards(reference)+walk)
readme='# Claude Agent SDK · Lesson 42 · File checkpointing and rewind\n\nFive linked student pages, large text, actual SDK experiments and coloured code in all thirteen UML steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson42-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson42-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations use `cd .\\agent-sdk\\lesson42-checkpointing`. Open http://127.0.0.1:3142 and keep the terminal running. Node.js 24+, API credit and model access are required. Windows may require Git Bash.\n\n## Create your .env file\n\nPreserve an existing file. Enter your own model key, then restart. Existing shell values take precedence.\n\n```dotenv\n'+env+'\n```\n\nNo GitHub token or Managed Agents IDs are required. Secrets, dependencies and teaching media stay outside Git.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for step in steps:readme+=f'### {step["number"]}. {step["title"]}\n\n{step["explanation"]}\n\nSource: `{step["source"]}`, selected lines {step["firstLine"]}–{step["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{step["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## References\n\n- [Official SDK file checkpointing documentation](https://code.claude.com/docs/en/agent-sdk/file-checkpointing)\n- [TypeScript SDK reference](https://code.claude.com/docs/en/agent-sdk/typescript)\n\nRegenerate student pages with `python scripts/build-pages.py`. Run `npm test` for guarded file operations, restore choices, real fixture validation and startup checks.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
print('Built five Lesson 42 pages and thirteen source-linked UML steps.')

(PUBLIC/"style.css").write_text((PUBLIC/"style.css").read_text(encoding="utf-8")+'\n#conversation{max-height:540px;overflow:auto}.markdown-body{font-size:22px;line-height:1.6}.markdown-body article,#conversation article{padding:16px;border-bottom:1px solid var(--line)}.json-view{max-height:380px}#result-history td{max-width:380px;overflow-wrap:anywhere}.table{max-height:350px;overflow:auto}#branch-cards{grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr))}#branch-cards .branch-card{padding:20px;overflow-wrap:anywhere}#branch-cards .meta{font-size:20px}#session-picker{font-size:21px}#picker-panel .meta{margin-bottom:0}\n',encoding="utf-8")
